<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.transfer');$id=max(1,(int)($_GET['id']??$_POST['id']??0));$st=db()->prepare('SELECT q.*,c.company_name FROM quotations q JOIN clients c ON c.id=q.client_id WHERE q.id=?');$st->execute([$id]);$quote=$st->fetch();if(!$quote){http_response_code(404);exit('Cotización no encontrada.');}$users=db()->query('SELECT id,name,email FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle='Transferir cotización';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$owner=max(0,(int)($_POST['owner_user_id']??0))?:null;db()->prepare('UPDATE quotations SET owner_user_id=? WHERE id=?')->execute([$owner,$id]);if($quote['deal_id']&&isset($_POST['transfer_deal']))db()->prepare('UPDATE deals SET owner_user_id=? WHERE id=?')->execute([$owner,(int)$quote['deal_id']]);if($owner){create_in_app_notification($owner,'Cotización asignada',$quote['quotation_number'].' · '.$quote['company_name'],'quote','quotation_view.php?id='.$id);}log_activity('Cotización transferida',(int)$quote['client_id'],null,'Nuevo responsable: '.($owner?:'sin asignar'),$id);flash('success','Responsable actualizado.');redirect('quotation_view.php?id='.$id);}require __DIR__.'/includes/header.php';?>
<form method="post" class="panel"><div class="panel-header"><div><h2><?=e($quote['quotation_number'])?> · <?=e($quote['company_name'])?></h2><span class="table-sub">Solo administradores o usuarios con permiso de transferencia pueden cambiar el responsable.</span></div><a class="btn btn-light" href="quotation_view.php?id=<?=$id?>">Cancelar</a></div><div class="panel-body form-grid three"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Nuevo responsable<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=(int)$u['id']?>" <?=(int)$quote['owner_user_id']===(int)$u['id']?'selected':''?>><?=e($u['name'].' · '.$u['email'])?></option><?php endforeach;?></select></label><?php if($quote['deal_id']):?><label class="checkbox-row"><input type="checkbox" name="transfer_deal" value="1" checked> Transferir también el negocio relacionado</label><?php endif;?><div class="full form-actions"><button class="btn btn-primary">TRANSFERIR</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
